// Читаємо збережені дані компанії/перевізника з сесії
let sessionData = {};
try {
  sessionData = JSON.parse($('Get Session').item.json.data || '{}');
} catch(e) {}

// Генеруємо SHORT поля замовника
let clientShort = sessionData.CLIENT_COMPANY || '';
clientShort = clientShort.replace("ТОВАРИСТВО З ОБМЕЖЕНОЮ ВІДПОВІДАЛЬНІСТЮ", "ТОВ");
clientShort = clientShort.replace("ФІЗИЧНА ОСОБА-ПІДПРИЄМЕЦЬ", "ФОП");
clientShort = clientShort.replace("ПРИВАТНЕ ПІДПРИЄМСТВО", "ПП");
sessionData.CLIENT_COMPANY_SHORT = clientShort.trim();
const clientParts = (sessionData.CLIENT_DIRECTOR || '').trim().split(/\s+/);
sessionData.CLIENT_DIRECTOR_SHORT = clientParts.length >= 3
  ? clientParts[0] + ' ' + clientParts[1][0] + '.' + clientParts[2][0] + '.'
  : sessionData.CLIENT_DIRECTOR || '';

// Генеруємо SHORT поля перевізника якщо є
let carrierShort = sessionData.CARRIER_COMPANY || '';
carrierShort = carrierShort.replace("ТОВАРИСТВО З ОБМЕЖЕНОЮ ВІДПОВІДАЛЬНІСТЮ", "ТОВ");
carrierShort = carrierShort.replace("ФІЗИЧНА ОСОБА-ПІДПРИЄМЕЦЬ", "ФОП");
carrierShort = carrierShort.replace("ПРИВАТНЕ ПІДПРИЄМСТВО", "ПП");
sessionData.CARRIER_COMPANY_SHORT = carrierShort.trim();
const carrierParts = (sessionData.CARRIER_DIRECTOR || '').trim().split(/\s+/);
sessionData.CARRIER_DIRECTOR_SHORT = carrierParts.length >= 3
  ? carrierParts[0] + ' ' + carrierParts[1][0] + '.' + carrierParts[2][0] + '.'
  : sessionData.CARRIER_DIRECTOR || '';

// Читаємо дані рейсу
const routeContent = $('OpenAI Route Parser').item.json.choices[0].message.content;
const routeData = JSON.parse(routeContent);

// Мержимо всі дані
const data = Object.assign({}, sessionData, routeData);

// Службові поля
data.CONTRACT_DATE = $now.toFormat('dd.MM.yyyy');
data.CONTRACT_NUMBER = $now.toFormat('ddMMyy') + '-' + $now.toFormat('HHmm');
data.TRANSPORT_TYPE = 'Вантажоперевезення';

// Будуємо запити на заміну плейсхолдерів
const requests = Object.entries(data).map(([key, value]) => ({
  replaceAllText: {
    containsText: { text: `{{${key}}}`, matchCase: true },
    replaceText: String(value || '')
  }
}));

return [{ json: { requests } }];

const content = $('OpenAI Company Parser').item.json.choices[0].message.content;
const start = content.indexOf('{');
const end = content.lastIndexOf('}');
const raw = content.substring(start, end + 1);
const clean = raw.replace(/\n/g, '').replace(/\r/g, '');
const data = JSON.parse(clean);

// Генеруємо CLIENT_COMPANY_SHORT з CLIENT_COMPANY
// ТОВАРИСТВО З ОБМЕЖЕНОЮ ВІДПОВІДАЛЬНІСТЮ 'Назва' → ТОВ 'Назва'
// ФІЗИЧНА ОСОБА-ПІДПРИЄМЕЦЬ Іваненко І.І. → ФОП Іваненко І.І.
let short = data.CLIENT_COMPANY || '';
short = short.replace("ТОВАРИСТВО З ОБМЕЖЕНОЮ ВІДПОВІДАЛЬНІСТЮ", "ТОВ");
short = short.replace("ФІЗИЧНА ОСОБА-ПІДПРИЄМЕЦЬ", "ФОП");
short = short.replace("ПРИВАТНЕ ПІДПРИЄМСТВО", "ПП");
data.CLIENT_COMPANY_SHORT = short.trim();

// Генеруємо CLIENT_DIRECTOR_SHORT з CLIENT_DIRECTOR
// Іваненко Іван Іванович → Іваненко І.І.
const director = data.CLIENT_DIRECTOR || '';
const parts = director.trim().split(/\s+/);
if (parts.length >= 3) {
  data.CLIENT_DIRECTOR_SHORT = parts[0] + ' ' + parts[1][0] + '.' + parts[2][0] + '.';
} else {
  data.CLIENT_DIRECTOR_SHORT = director;
}

return [{ json: { companyData: JSON.stringify(data) } }];

const content = $('OpenAI Carrier Parser').item.json.choices[0].message.content;
const start = content.indexOf('{');
const end = content.lastIndexOf('}');
const raw = content.substring(start, end + 1);
const clean = raw.replace(/\n/g, '').replace(/\r/g, '');
const data = JSON.parse(clean);

let short = data.CARRIER_COMPANY || '';
short = short.replace("ТОВАРИСТВО З ОБМЕЖЕНОЮ ВІДПОВІДАЛЬНІСТЮ", "ТОВ");
short = short.replace("ФІЗИЧНА ОСОБА-ПІДПРИЄМЕЦЬ", "ФОП");
short = short.replace("ПРИВАТНЕ ПІДПРИЄМСТВО", "ПП");
data.CARRIER_COMPANY_SHORT = short.trim();

const director = data.CARRIER_DIRECTOR || '';
const parts = director.trim().split(/\s+/);
if (parts.length >= 3) {
  data.CARRIER_DIRECTOR_SHORT = parts[0] + ' ' + parts[1][0] + '.' + parts[2][0] + '.';
} else {
  data.CARRIER_DIRECTOR_SHORT = director;
}

return [{ json: { companyData: JSON.stringify(data) } }];

let userText = '';
const tgMessage = $('Telegram Trigger').first().json.message;

if (tgMessage && tgMessage.text !== undefined) {
  userText = tgMessage.text;
} else if (tgMessage && tgMessage.voice !== undefined) {
  userText = $('Whisper').first().json.text || '';
} else if (tgMessage && tgMessage.document !== undefined &&
           tgMessage.document.mime_type &&
           tgMessage.document.mime_type.includes('word')) {
  const binaryBuffer = await this.helpers.getBinaryDataBuffer(0, 'data');
  userText = binaryBuffer.toString('utf-8');
} else if (tgMessage && tgMessage.document !== undefined &&
           tgMessage.document.mime_type &&
           tgMessage.document.mime_type.includes('pdf')) {
  let pdfData = $('Analyze PDF (OpenAI)').first().json;
  if (Array.isArray(pdfData)) pdfData = pdfData[0];
  if (pdfData?.output?.[0]?.content?.[0]?.text) {
    userText = pdfData.output[0].content[0].text;
  } else {
    userText = '';
  }
} else {
  let visionData = $('OpenAI Vision').first().json;
  if (Array.isArray(visionData)) visionData = visionData[0];
  if (visionData?.content?.[0]?.logprobs?.text) {
    userText = visionData.content[0].logprobs.text;
  } else if (visionData?.content?.[0]?.text) {
    userText = visionData.content[0].text;
  } else if (typeof visionData?.content === 'string') {
    userText = visionData.content;
  }
}
return [{json: {userText}}];;

const binaryBuffer = await this.helpers.getBinaryDataBuffer(0, 'data');
const base64String = binaryBuffer.toString('base64');
const fileName = $('Telegram Trigger').first().json.message.document.file_name || 'document.pdf';

return [{json: {pdfBase64: base64String, fileName}}];

