const content = $('OpenAI Route Parser').item.json.choices[0].message.content;
const start = content.indexOf('{');
const end = content.lastIndexOf('}');
const raw = content.substring(start, end + 1);

// Прибираємо \n та \r — Groq часто їх вставляє незважаючи на промпт
const clean = raw.replace(/\n/g, '').replace(/\r/g, '');

const routeData = JSON.parse(clean);

let sessionData = {};
try {
  sessionData = JSON.parse($('Get Session').item.json.data || '{}');
} catch(e) {
  sessionData = {};
}

const merged = Object.assign(sessionData, routeData);
return [{ json: { merged: JSON.stringify(merged) } }];
